"use client"

/**
 * Gaps composed locally for this prototype — logged as CAND-001 (Avatar) and
 * CAND-005 (SegmentedControl) in atlas/state/candidates.json.
 */

import { Button } from "@atlas/ui-web/primitives/Button/Button"

function initials(name: string) {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("")
}

export function Avatar({ name, src }: { name: string; src?: string }) {
  const size = "var(--atlas-spacing-12)"
  const style: React.CSSProperties = {
    width: size,
    height: size,
    borderRadius: "var(--atlas-radius-full)",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    flexShrink: 0,
    overflow: "hidden",
    backgroundColor: "var(--atlas-primary-subtle)",
    color: "var(--atlas-primary)",
    fontSize: "var(--atlas-font-size-lg)",
    fontWeight: "var(--atlas-font-weight-semibold)" as unknown as number,
  }

  if (src) {
    return (
      <span style={style}>
        <img
          src={src}
          alt=""
          style={{ width: "100%", height: "100%", objectFit: "cover" }}
        />
      </span>
    )
  }

  return (
    <span style={style} role="img" aria-label={name}>
      {initials(name)}
    </span>
  )
}

export type ThemeChoice = "light" | "dark" | "system"

const THEME_OPTIONS: { value: ThemeChoice; label: string }[] = [
  { value: "light", label: "Light" },
  { value: "dark", label: "Dark" },
  { value: "system", label: "System" },
]

export function SegmentedControl({
  value,
  onChange,
  label,
}: {
  value: ThemeChoice
  onChange: (value: ThemeChoice) => void
  label: string
}) {
  return (
    <div
      role="group"
      aria-label={label}
      style={{
        display: "flex",
        gap: "var(--atlas-spacing-1)",
        padding: "var(--atlas-spacing-1)",
        backgroundColor: "var(--atlas-background-muted)",
        borderRadius: "var(--atlas-radius-md)",
      }}
    >
      {THEME_OPTIONS.map((option) => (
        <Button
          key={option.value}
          type="button"
          variant={value === option.value ? "secondary" : "ghost"}
          size="sm"
          aria-pressed={value === option.value}
          onClick={() => onChange(option.value)}
          style={{ flex: 1 }}
        >
          {option.label}
        </Button>
      ))}
    </div>
  )
}

